<?php require '../config.php';require_admin();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$s=$pdo->prepare("SELECT * FROM products WHERE id=?");$s->execute([$id]);$row=$s->fetch();if(!$row)exit('Product not found');$cats=$pdo->query("SELECT * FROM categories ORDER BY name")->fetchAll();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['pname']??'');$cat=(int)($_POST['category_id']??0);$price=$_POST['price']??'';if($name===''||!is_numeric($price)||$price<0||!in_array($cat,array_column($cats,'id')))$error='Enter valid details.';else{$pic=$row['picture'];if(isset($_FILES['picture'])&&$_FILES['picture']['error']!==UPLOAD_ERR_NO_FILE){$error='For this starter version, leave image unchanged while editing. Use Add Product to upload a resized image.';}if(!$error){$s=$pdo->prepare("UPDATE products SET category_id=?,pname=?,price=? WHERE id=?");$s->execute([$cat,$name,$price,$id]);header('Location: products.php');exit;}}}?><!doctype html><html><head><meta charset="utf-8"><title>Edit product</title><link rel="stylesheet" href="../assets/style.css"></head><body><main><h1>Edit Product</h1><p class="error"><?=h($error)?></p><form method="post"><label>Name<input name="pname" value="<?=h($row['pname'])?>" required></label><label>Category<select name="category_id"><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$c['id']==$row['category_id']?'selected':''?>><?=h($c['name'])?></option><?php endforeach;?></select></label><label>Price<input type="number" name="price" min="0" step="0.01" value="<?=h($row['price'])?>" required></label><p>Current picture: <?=h($row['picture'])?> (picture replacement not included in this starter edit form)</p><button>Update</button></form><a href="products.php">Back</a></main></body></html>